const SPREADSHEET_ID = "1J8O-BZlgJa9e3X-8lNnpu9od4R9oghNbnCCBhnl8jys";

function doGet(e) {
  // Soporte para verificación de conexión (ping)
  if (e && e.parameter && e.parameter.action === "ping") {
    return ContentService.createTextOutput(JSON.stringify({
      success: true,
      message: "Apps Script Web App activa y conectada",
      timestamp: new Date().toISOString()
    })).setMimeType(ContentService.MimeType.JSON);
  }

  const template = HtmlService.createTemplateFromFile('Index');
  let webAppUrl = "";
  try {
    webAppUrl = ScriptApp.getService().getUrl();
  } catch (err) {
    webAppUrl = "";
  }
  template.webAppUrl = webAppUrl;

  return template.evaluate()
    .setTitle('Menú Digital Restaurante')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL)
    .addMetaTag('viewport', 'width=device-width, initial-scale=1.0');
}

/**
 * Obtiene la hoja de cálculo correcta (activa, por parámetro o por ID configurado)
 */
function getTargetSpreadsheet(data) {
  // 1. Si el script está dentro de la hoja de cálculo (Extensiones > Apps Script)
  try {
    const active = SpreadsheetApp.getActiveSpreadsheet();
    if (active) return active;
  } catch(e) {}
  
  // 2. Si el ID viene en la petición enviada por la aplicación
  if (data && data.spreadsheetId) {
    try {
      const byParam = SpreadsheetApp.openById(data.spreadsheetId);
      if (byParam) return byParam;
    } catch(e) {}
  }
  
  // 3. Fallback al SPREADSHEET_ID predeterminado
  return SpreadsheetApp.openById(SPREADSHEET_ID);
}

/**
 * Función de prueba para verificar permisos y conexión desde el editor de Apps Script
 * Puedes seleccionarla arriba y presionar "Ejecutar"
 */
function probarConexion() {
  const ss = getTargetSpreadsheet({});
  Logger.log("✅ Conectado a la hoja: " + ss.getName() + " (ID: " + ss.getId() + ")");
  
  let sheet = ss.getSheetByName("pedidoDelivery");
  if (!sheet) {
    sheet = ss.insertSheet("pedidoDelivery");
    const headers = [
      "IdPedido", "Fecha", "Hora", "Nombre Cliente", "Cedula /Rif",
      "Telefono", "Detalle Productos", "Ubicacion Google Map",
      "Foto Pago", "Nro de Referencia", "Entrega"
    ];
    sheet.appendRow(headers);
    const headerRange = sheet.getRange(1, 1, 1, headers.length);
    headerRange.setFontWeight("bold");
    headerRange.setBackground("#1c1917");
    headerRange.setFontColor("#ffffff");
    sheet.setFrozenRows(1);
    Logger.log("✅ Pestaña 'pedidoDelivery' creada con éxito.");
  } else {
    Logger.log("✅ Pestaña 'pedidoDelivery' ya existe.");
  }
  
  try {
    let folder;
    const folderIter = DriveApp.getFoldersByName("Pagos Fotos");
    if (folderIter.hasNext()) {
      folder = folderIter.next();
      Logger.log("✅ Carpeta 'Pagos Fotos' encontrada en Drive.");
    } else {
      folder = DriveApp.createFolder("Pagos Fotos");
      Logger.log("✅ Carpeta 'Pagos Fotos' creada en Drive.");
    }
  } catch(dErr) {
    Logger.log("⚠️ Verificación Drive: " + dErr.message);
  }
  
  Logger.log("🎉 ¡Todo listo! Permisos y sincronización verificados.");
  return "OK";
}

/**
 * Obtiene los datos del restaurante, los platos de la hoja de cálculo y la URL pública
 */
function getMenuData() {
  try {
    const ss = getTargetSpreadsheet({});
    
    // 1. Obtener valores de la hoja "URL"
    const urlSheet = ss.getSheetByName("URL");
    const urlData = urlSheet ? urlSheet.getDataRange().getValues() : [];
    
    let tasaBCV = 846.25;
    let tasaBCVTexto = "846,25";
    let nombreRestaurante = "Restaurante";
    let telefono = "";
    
    for (let i = 0; i < urlData.length; i++) {
      const colA = String(urlData[i][0] || "").trim();
      const colB = urlData[i][1];
      
      if (colA.toLowerCase().indexOf("tasa bcv") !== -1) {
        tasaBCVTexto = String(colB);
        const normalizado = String(colB).replace(',', '.');
        tasaBCV = parseFloat(normalizado) || 846.25;
      } else if (colA.toLowerCase().indexOf("restaurante") !== -1) {
        nombreRestaurante = String(colB || "").trim();
      } else if (colA.toLowerCase().indexOf("telefono") !== -1) {
        telefono = String(colB || "").trim();
      }
    }
    
    // 2. Obtener platos de la hoja "Platos"
    const platosSheet = ss.getSheetByName("Platos");
    const platosData = platosSheet ? platosSheet.getDataRange().getValues() : [];
    
    const platos = [];
    for (let r = 1; r < platosData.length; r++) {
      const row = platosData[r];
      const colA = String(row[0] || "").trim();
      const colB = String(row[1] || "").trim();
      const nombrePlato = colB || colA;
      
      if (!nombrePlato) continue;
      
      const categoria = String(row[2] || "Platos Fuertes").trim();
      const precioUSD = parseFloat(String(row[3] || "0").replace(',', '.')) || 0;
      const precioBs = Number((precioUSD * tasaBCV).toFixed(2));
      const descripcion = String(row[4] || "").trim();
      const dispRaw = String(row[5] || "SI").trim().toUpperCase();
      const disponible = (dispRaw === "SI" || dispRaw === "SÍ" || dispRaw === "TRUE" || dispRaw === "1");
      const fotoUrl = String(row[8] || "").trim();
      const contornosRaw = String(row[9] || "").trim();
      let contornos = [];
      if (contornosRaw) {
        const limpiado = contornosRaw
          .split(String.fromCharCode(10)).join(",")
          .split(String.fromCharCode(13)).join(",")
          .split(";").join(",");
        contornos = limpiado
          .split(",")
          .map(function(s) { return s.trim(); })
          .filter(Boolean);
      }
      
      platos.push({
        id: colA || ("plato-" + r),
        nombre: nombrePlato,
        categoria: categoria,
        precioUSD: precioUSD,
        precioBs: precioBs,
        descripcion: descripcion,
        disponible: disponible,
        fotoUrl: fotoUrl,
        contornos: contornos,
        contornosRaw: contornosRaw
      });
    }

    let publicUrl = "";
    try {
      publicUrl = ScriptApp.getService().getUrl();
    } catch(e) {}
    
    return {
      success: true,
      restaurante: nombreRestaurante,
      telefono: telefono,
      tasaBCV: tasaBCV,
      tasaBCVTexto: tasaBCVTexto,
      platos: platos,
      publicUrl: publicUrl,
      actualizado: new Date().toISOString()
    };
  } catch (error) {
    return {
      success: false,
      error: error.message
    };
  }
}

/**
 * Procesa la recepción de pedidos desde el modal (POST)
 * Guarda en la hoja "pedidoDelivery" y sube la foto a la carpeta "Pagos Fotos" en Google Drive
 */
function doPost(e) {
  try {
    let data = {};
    if (e && e.postData && e.postData.contents) {
      try {
        data = JSON.parse(e.postData.contents);
      } catch(pErr) {
        data = e.parameter || {};
      }
    } else if (e && e.parameter) {
      data = e.parameter;
    }
    
    const res = registrarPedidoDelivery(data);
    return ContentService.createTextOutput(JSON.stringify(res))
      .setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({
      success: false,
      error: err.toString()
    })).setMimeType(ContentService.MimeType.JSON);
  }
}

/**
 * Función que registra el pedido en la hoja "pedidoDelivery" y guarda la foto en Google Drive
 */
function registrarPedidoDelivery(data) {
  const ss = getTargetSpreadsheet(data);
  
  // 1. Obtener o crear la hoja "pedidoDelivery"
  let sheet = ss.getSheetByName("pedidoDelivery");
  if (!sheet) {
    sheet = ss.insertSheet("pedidoDelivery");
    // Encabezados exactos especificados
    const headers = [
      "IdPedido",
      "Fecha",
      "Hora",
      "Nombre Cliente",
      "Cedula /Rif",
      "Telefono",
      "Detalle Productos",
      "Ubicacion Google Map",
      "Foto Pago",
      "Nro de Referencia",
      "Entrega"
    ];
    sheet.appendRow(headers);
    const headerRange = sheet.getRange(1, 1, 1, headers.length);
    headerRange.setFontWeight("bold");
    headerRange.setBackground("#1c1917");
    headerRange.setFontColor("#ffffff");
    sheet.setFrozenRows(1);
  }
  
  // 2. Calcular IdPedido autoincremental formato "P-0000001"
  const colAValues = sheet.getRange("A:A").getValues();
  let maxIdNum = 0;
  for (let r = 1; r < colAValues.length; r++) {
    const val = String(colAValues[r][0] || "").trim().toUpperCase();
    if (val.indexOf("P-") === 0) {
      const num = parseInt(val.substring(2), 10);
      if (!isNaN(num) && num > maxIdNum) {
        maxIdNum = num;
      }
    }
  }
  const nextNum = maxIdNum + 1;
  const idPedido = "P-" + ("0000000" + nextNum).slice(-7);
  
  // 3. Fecha (latinoamericano DD/MM/AAAA) y Hora (am/pm)
  const tz = "America/Caracas";
  const now = new Date();
  const fecha = Utilities.formatDate(now, tz, "dd/MM/yyyy");
  const hora = Utilities.formatDate(now, tz, "hh:mm a");
  
  // 4. Subir Foto Pago a Google Drive en carpeta "Pagos Fotos"
  let fotoUrl = "";
  try {
    if (data.fotoPagoBase64 && String(data.fotoPagoBase64).trim()) {
      let folder;
      const folderIter = DriveApp.getFoldersByName("Pagos Fotos");
      if (folderIter.hasNext()) {
        folder = folderIter.next();
      } else {
        folder = DriveApp.createFolder("Pagos Fotos");
      }
      
      let base64Data = String(data.fotoPagoBase64);
      let mimeType = "image/jpeg";
      if (base64Data.indexOf(";base64,") !== -1) {
        const parts = base64Data.split(";base64,");
        mimeType = parts[0].replace("data:", "") || "image/jpeg";
        base64Data = parts[1];
      }
      
      const decodedBytes = Utilities.base64Decode(base64Data);
      const cleanCedula = String(data.cedulaRif || "cliente").replace(/[^a-zA-Z0-9_-]/g, "");
      const dateStamp = Utilities.formatDate(now, tz, "yyyyMMdd_HHmmss");
      const fileName = "Pago_" + idPedido + "_" + cleanCedula + "_" + dateStamp + ".jpg";
      
      const blob = Utilities.newBlob(decodedBytes, mimeType, fileName);
      const file = folder.createFile(blob);
      try {
        file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
      } catch(shareErr) {}
      
      const fileId = file.getId();
      fotoUrl = "https://drive.google.com/thumbnail?id=" + fileId + "&sz=w1000";
    } else if (data.fotoPagoUrl) {
      fotoUrl = String(data.fotoPagoUrl);
    }
  } catch (driveErr) {
    fotoUrl = "Error Drive: " + driveErr.message;
  }
  
  // 5. Preparar fila con las 11 columnas
  const rowData = [
    idPedido,                                // Columna A: IdPedido
    fecha,                                   // Columna B: Fecha
    hora,                                    // Columna C: Hora
    String(data.nombreCliente || "").trim(), // Columna D: Nombre Cliente
    String(data.cedulaRif || "").trim(),     // Columna E: Cedula /Rif
    String(data.telefono || "").trim(),      // Columna F: Telefono
    String(data.detalleProductos || "").trim(), // Columna G: Detalle Productos
    String(data.ubicacionGoogleMap || "").trim(), // Columna H: Ubicacion Google Map
    fotoUrl,                                 // Columna I: Foto Pago
    String(data.nroReferencia || "").trim(), // Columna J: Nro de Referencia
    String(data.entrega || "Delivery").trim() // Columna K: Entrega
  ];
  
  sheet.appendRow(rowData);
  
  return {
    success: true,
    idPedido: idPedido,
    fecha: fecha,
    hora: hora,
    fotoUrl: fotoUrl,
    message: "Pedido " + idPedido + " registrado exitosamente en pedidoDelivery"
  };
}
